const claim = $input.first().json;
const s = claim.session || {};
const ctx = (s.context && typeof s.context === 'object' && !Array.isArray(s.context)) ? s.context : {};
const KNOWN = ['MAIN_MENU', 'SELECT_SERVICE', 'SELECT_PROFESSIONAL', 'SELECT_DAY', 'SELECT_TIME', 'ASK_NAME', 'CONFIRM', 'MY_APPOINTMENTS', 'APPOINTMENT_ACTION', 'CONFIRM_CANCEL'];
const invalidCount = Number(s.invalidCount) || 0;
const bot = {
  inboundEventId: claim.inboundEventId,
  instance: claim.instance || {},
  to: claim.to,
  contact: claim.contact || {},
  session: { id: s.id, state: s.state, version: s.version, lockToken: s.lockToken, invalidCount, expired: !!s.expired },
  context: ctx,
  tenant: claim.tenant || {},
  texts: claim.texts || {},
};
const norm = (t) => String(t == null ? '' : t).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const base = { nextState: s.state, contextPatch: {}, resetContext: false, keepPage: false, textKey: null, vars: {}, options: null, handoff: false, prefixKey: null, repeatPrompt: false, invalidCount: 0, end: false };
const pronto = (r) => [{ json: { step: 'PRONTO', bot, choice: null, result: Object.assign({}, base, r) } }];
const siga = (choice) => [{ json: { step: s.state, bot, choice } }];

const isText = !!claim.message && claim.message.type === 'text';
const text = isText ? String(claim.message.text || '').trim() : '';
const options = Array.isArray(ctx.options) ? ctx.options : [];

const fresh = bot.session.expired || !KNOWN.includes(s.state) || (s.state === 'MAIN_MENU' && options.length === 0);
if (fresh) {
  return pronto({ nextState: 'MAIN_MENU', resetContext: true, prefixKey: bot.session.expired ? 'SESSION_EXPIRED' : 'GREETING', textKey: isText ? null : 'ONLY_TEXT' });
}
if (!isText) return pronto({ textKey: 'ONLY_TEXT', repeatPrompt: true, invalidCount });

const t = norm(text);
if (t === '0' || t === 'menu') return pronto({ nextState: 'MAIN_MENU', resetContext: true });
if (t === 'sair') return pronto({ nextState: 'MAIN_MENU', resetContext: true, textKey: 'GOODBYE', end: true });

if (s.state === 'ASK_NAME') {
  const name = text.replace(/\s+/g, ' ');
  if (name.length >= 2 && name.length <= 60 && !/^[0-9]+$/.test(name)) return siga({ id: name, label: name });
} else {
  let found = null;
  if (/^[0-9]+$/.test(t)) {
    found = options.find((o) => Number(o.n) === parseInt(t, 10)) || null;
  } else if (t.length > 0) {
    const exact = options.filter((o) => norm(o.label) === t);
    const prefix = options.filter((o) => norm(o.label).startsWith(t));
    found = exact.length === 1 ? exact[0] : (prefix.length === 1 ? prefix[0] : null);
  }
  if (found && found.id === '__page_next') {
    return pronto({ options: Array.isArray(ctx.allOptions) ? ctx.allOptions : options, keepPage: true, contextPatch: { page: (Number(ctx.page) || 0) + 1 }, textKey: ctx.lastTextKey || null, vars: ctx.lastVars || {} });
  }
  if (found) return siga({ id: found.id, label: found.label });
}

const count = invalidCount + 1;
if (count >= 3) return pronto({ nextState: 'HUMAN', resetContext: true, textKey: 'TOO_MANY_INVALID', handoff: true });
return pronto({ textKey: 'INVALID_OPTION', repeatPrompt: true, invalidCount: count });

const I = $('Interpretar').first().json;
const bot = I.bot;
const r = Object.assign({ contextPatch: {}, vars: {}, invalidCount: 0 }, ($input.first().json || {}).result || {});
const texts = bot.texts || {};
const oldCtx = bot.context || {};
const L = (key, fallback) => (typeof texts[key] === 'string' && texts[key].trim()) ? texts[key].trim() : fallback;
const SPECIAL_LABELS = { __more_days: L('LABEL_MORE_DAYS', 'Ver mais datas'), __more_times: L('LABEL_MORE_TIMES', 'Mais horários'), __page_next: L('LABEL_MORE', 'Ver mais') };
const MENUS = {
  MAIN_MENU: { render: false, footer: false, options: [{ id: 'agendar', label: 'Agendar horário' }, { id: 'meus', label: 'Meus agendamentos' }, { id: 'atendente', label: 'Falar com atendente' }] },
  APPOINTMENT_ACTION: { render: false, footer: true, options: [{ id: 'cancelar', label: 'Cancelar' }, { id: 'remarcar', label: 'Remarcar' }] },
  CONFIRM: { render: true, footer: true, options: [{ id: 'confirmar', label: L('LABEL_CONFIRM', 'Confirmar') }, { id: 'outro', label: L('LABEL_OTHER_TIME', 'Escolher outro horário') }] },
  CONFIRM_CANCEL: { render: true, footer: true, options: [{ id: 'sim', label: L('LABEL_CANCEL_YES', 'Sim, cancelar') }, { id: 'nao', label: L('LABEL_CANCEL_NO', 'Não, manter') }] },
};
const vars = Object.assign({ nome: bot.contact.name || bot.contact.pushName || '', empresa: bot.tenant.name || '' }, r.vars || {});
const render = (key) => {
  if (!key || typeof texts[key] !== 'string') return '';
  return texts[key].replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null) ? m : String(vars[k])).trim();
};

let nextState = r.nextState || bot.session.state;
let ctx;
let message;
if (r.repeatPrompt && oldCtx.lastPrompt) {
  ctx = Object.assign({}, oldCtx);
  message = [render(r.textKey), oldCtx.lastPrompt].filter(Boolean).join('\n\n');
} else {
  let resetContext = !!r.resetContext;
  if (r.repeatPrompt) { nextState = 'MAIN_MENU'; resetContext = true; }
  ctx = resetContext ? {} : Object.assign({}, oldCtx);
  Object.assign(ctx, r.contextPatch || {});
  const closing = !!r.end || !!r.handoff || nextState === 'HUMAN';
  const menu = MENUS[nextState];
  const blocks = [];
  if (r.prefixKey) blocks.push(render(r.prefixKey));
  let heading = '';
  let opts = Array.isArray(r.options) ? r.options : [];
  let renderOpts = true;
  let footer = true;
  if (closing) {
    blocks.push(render(r.textKey));
    opts = []; renderOpts = false; footer = false;
  } else if (nextState === 'MAIN_MENU') {
    blocks.push(render(r.textKey));
    heading = render('MAIN_MENU');
    opts = menu.options; renderOpts = false; footer = false;
  } else if (menu && opts.length === 0) {
    heading = render(r.textKey);
    opts = menu.options; renderOpts = menu.render; footer = menu.footer;
  } else {
    heading = render(r.textKey);
  }
  const regular = opts.filter((o) => !String(o.id).startsWith('__'));
  const special = opts.filter((o) => String(o.id).startsWith('__') && o.id !== '__page_next');
  let shown;
  if (regular.length + special.length > 9) {
    const pages = Math.ceil(regular.length / 8);
    const page = r.keepPage ? ((Number(ctx.page) || 0) % pages) : 0;
    shown = regular.slice(page * 8, page * 8 + 8).map((o, i) => ({ n: i + 1, id: o.id, label: o.label }));
    shown.push({ n: 9, id: '__page_next', label: SPECIAL_LABELS.__page_next });
    ctx.allOptions = opts;
    ctx.page = page;
  } else {
    shown = regular.map((o, i) => ({ n: i + 1, id: o.id, label: o.label })).concat(special.map((o) => ({ n: Number(o.n), id: o.id, label: SPECIAL_LABELS[o.id] || o.label })));
    delete ctx.allOptions;
    delete ctx.page;
  }
  const lines = [];
  if (heading) lines.push(heading);
  if (renderOpts && shown.length) lines.push(shown.map((o) => o.n + '. ' + o.label).join('\n'));
  if (footer) lines.push(L('LABEL_BACK_TO_MENU', '0. Menu principal'));
  const prompt = lines.join('\n');
  if (prompt) blocks.push(prompt);
  message = blocks.filter(Boolean).join('\n\n');
  if (closing) {
    ctx = {};
  } else {
    ctx.options = shown;
    ctx.lastPrompt = prompt;
    ctx.lastTextKey = r.textKey || null;
    ctx.lastVars = r.vars || {};
  }
}
if (!message) message = render('MAIN_MENU') || '0. Menu principal';

return [{ json: {
  sessionId: bot.session.id,
  sandbox: !!(bot.instance && bot.instance.sandbox),
  instanceName: bot.instance ? bot.instance.name : '',
  save: { lockToken: bot.session.lockToken, version: bot.session.version, state: nextState, context: ctx, invalidCount: Number(r.invalidCount) || 0, outbound: [message], handoff: !!r.handoff },
  messages: [{ number: bot.to, text: message }],
} }];

