const choice = I.choice || {};
const R = (result) => [{ json: { result } }];
const res = $input.first().json;
const status = Number(res.statusCode);
const body = res.body || {};
if ((status === 200 || status === 201) && body.appointment) {
  const s = body.appointment.summary || {};
  return R({ nextState: 'MAIN_MENU', resetContext: true, textKey: 'BOOKED', vars: { servico: s.servico, profissional: s.profissional, data: s.data, hora: s.hora } });
}
const err = body.error || {};
if (status === 409 && err.code === 'SLOT_TAKEN') {
  const alt = (err.details && err.details.alternatives) || {};
  const opts = (alt.options || []).map((o) => ({ id: o.id, label: o.label }));
  if (!opts.length) return R({ nextState: 'MAIN_MENU', resetContext: true, textKey: 'NO_AVAILABILITY' });
  return R({ nextState: 'SELECT_TIME', contextPatch: { date: null, dayLabel: alt.date || '', slotOffset: 0 }, textKey: 'SLOT_TAKEN', options: opts });
}
if (status === 422 || status === 403) return R({ nextState: 'MAIN_MENU', resetContext: true, textKey: 'NO_AVAILABILITY' });
if (status === 404) return R({ nextState: 'MAIN_MENU', resetContext: true });
throw new Error('POST /appointments respondeu HTTP ' + status + (err.code ? ' ' + err.code : ''));

